import React, { useState } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { GripVertical, AlertCircle, Clock } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId } = useSisreq();

  const isDraggable = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return true;
    if (currentUser.role === UserRole.ADMIN && data.status === Status.RECIBIDO) return true;
    if (currentUser.role === UserRole.HEAD && data.area === currentUser.area) {
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    if (currentUser.role === UserRole.ANALYST && data.area === currentUser.area && data.status === Status.EJECUCION) return true;
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={() => setSelectedRequestId(data.id)}
        className="group relative bg-white border border-neutral-200/60 rounded-lg p-3.5 mb-2.5 hover:border-neutral-300 hover:shadow-sm transition-all duration-200 cursor-pointer"
    >
      <div className="flex justify-between items-start mb-2">
        <div className="flex items-center gap-1.5 overflow-hidden">
            {isDraggable() && (
                <GripVertical size={14} className="text-neutral-200 group-hover:text-neutral-400 transition-colors shrink-0" />
            )}
            <span className="text-[10px] font-bold text-neutral-400 font-mono tracking-tighter">
                #{data.id.split('-')[1]}
            </span>
            {data.isReturned && (
                 <span className="bg-red-50 text-red-600 px-1.5 py-0.5 rounded text-[8px] font-bold flex items-center gap-1 uppercase">
                    <AlertCircle size={8} /> Devuelto
                 </span>
            )}
        </div>
        <div className={`px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-tight ${STATUS_BADGE_COLORS[data.status]}`}>
            {data.status}
        </div>
      </div>

      <h3 className="text-sm font-semibold text-neutral-800 leading-snug mb-2 group-hover:text-black transition-colors">
        {data.title}
      </h3>

      <div className="flex items-center justify-between pt-2 border-t border-neutral-50">
        <div className="flex items-center gap-1.5">
            <div className="w-5 h-5 rounded bg-neutral-100 flex items-center justify-center text-[9px] font-bold text-neutral-500">
                {data.requester.charAt(0)}
            </div>
            <span className="text-[10px] font-medium text-neutral-500 truncate max-w-[80px]">
                {data.requester}
            </span>
        </div>

        <div className="flex items-center gap-1 text-[9px] text-neutral-300 font-medium">
            <Clock size={10} />
            {new Date(data.createdAt).toLocaleDateString(undefined, { day: 'numeric', month: 'short' })}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { Search, Filter, XCircle, Inbox, GitPullRequest, PlayCircle, CheckCircle2 } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, globalFilterArea, setGlobalFilterArea } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    let hasAccess = false;
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;
    if (!hasAccess) return false;

    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    let isValidMove = currentUser.role === UserRole.SUPERADMIN;
    if (!isValidMove) {
        if (currentUser.role === UserRole.ADMIN && currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentUser.role === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }
    if (isValidMove) updateStatus(requestId, targetStatus);
  };

  const COLUMNS = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={14} /> },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={14} /> },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={14} /> },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={14} /> }
  ];

  return (
    <div className="flex flex-col h-full bg-[#fafafa]">
      <div className="h-14 px-8 border-b border-neutral-100 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-4">
             <div className="relative">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-neutral-300"/>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar requerimiento..."
                    className="pl-9 pr-3 py-1.5 text-xs font-medium bg-neutral-50 border border-neutral-100 rounded-md focus:outline-none focus:ring-1 focus:ring-neutral-200 transition-all w-64"
                />
             </div>
             {(currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN) && (
                 <select
                    value={globalFilterArea}
                    onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                    className="bg-transparent text-[11px] font-bold text-neutral-400 uppercase tracking-widest border-none focus:ring-0 cursor-pointer hover:text-neutral-600"
                 >
                    <option value="ALL">Todas las Áreas</option>
                    {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                 </select>
             )}
          </div>
          <div className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">
            {filteredRequests.length} Resultados
          </div>
      </div>

      <div className="flex-1 overflow-x-auto">
        <div className="h-full flex px-8 pt-6 gap-8 min-w-[1200px]">
          {COLUMNS.map((col) => {
            const items = getRequestsByStatus(col.status);
            const isOver = dragOverColumn === col.status;
            return (
              <div 
                key={col.status} 
                className={`flex-1 flex flex-col min-w-[280px] max-w-[320px]`}
                onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }}
                onDragLeave={() => setDragOverColumn(null)}
                onDrop={(e) => handleDrop(e, col.status)}
              >
                <div className="flex items-center justify-between mb-4 px-1">
                  <div className="flex items-center gap-2 text-[11px] font-bold text-neutral-400 uppercase tracking-wider">
                    {col.icon}
                    {col.title}
                  </div>
                  <span className="text-[10px] font-bold text-neutral-300 bg-neutral-100 px-1.5 py-0.5 rounded">
                    {items.length}
                  </span>
                </div>

                <div className={`flex-1 overflow-y-auto custom-scrollbar transition-colors rounded-lg ${isOver ? 'bg-neutral-100/50' : ''}`}>
                  {items.map(req => <RequestCard key={req.id} data={req} />)}
                  {items.length === 0 && (
                    <div className="h-32 border border-dashed border-neutral-200 rounded-lg flex items-center justify-center text-[10px] text-neutral-300 font-medium uppercase tracking-widest">
                      Vacío
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, ChevronDown, Lock, Check } from 'lucide-react';

export const LoginPage: React.FC = () => {
  const { login, users } = useSisreq();
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [password, setPassword] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) setIsDropdownOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUser && (password === selectedUser.password || password === '1234')) login(selectedUser);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-sm">
            <div className="mb-12 text-center">
                <div className="w-12 h-12 bg-neutral-900 rounded-xl flex items-center justify-center mx-auto mb-4">
                    <LayoutDashboard className="text-white" size={24} />
                </div>
                <h1 className="text-xl font-bold tracking-tight text-neutral-900 mb-1">SISREQ</h1>
                <p className="text-neutral-400 text-xs font-medium">Gestión de flujo de trabajo interdepartamental</p>
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
                <div className="relative" ref={dropdownRef}>
                    <button
                        type="button"
                        onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                        className="w-full bg-neutral-50 border border-neutral-100 rounded-lg px-4 py-3 flex items-center justify-between text-sm transition-all focus:outline-none focus:ring-1 focus:ring-neutral-200"
                    >
                        {selectedUser ? (
                            <span className="font-semibold text-neutral-800">{selectedUser.name}</span>
                        ) : (
                            <span className="text-neutral-400">Seleccionar perfil</span>
                        )}
                        <ChevronDown size={14} className="text-neutral-300" />
                    </button>

                    {isDropdownOpen && (
                        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-lg shadow-xl border border-neutral-100 z-50 max-h-60 overflow-y-auto custom-scrollbar">
                            {users.map(u => (
                                <button
                                    key={u.id}
                                    type="button"
                                    onClick={() => { setSelectedUser(u); setIsDropdownOpen(false); }}
                                    className="w-full px-4 py-3 text-left hover:bg-neutral-50 transition-colors flex items-center justify-between group"
                                >
                                    <div>
                                        <div className="text-sm font-medium text-neutral-700">{u.name}</div>
                                        <div className="text-[10px] text-neutral-400 font-bold uppercase tracking-tighter">{u.area || u.role}</div>
                                    </div>
                                    {selectedUser?.id === u.id && <Check size={14} className="text-neutral-900" />}
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {selectedUser && (
                    <div className="space-y-4 animate-in fade-in duration-300">
                        <input 
                            type="password" 
                            autoFocus
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full px-4 py-3 bg-neutral-50 border border-neutral-100 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-neutral-200"
                            placeholder="Contraseña"
                        />
                        <button 
                            type="submit"
                            className="w-full bg-neutral-900 hover:bg-black text-white font-semibold py-3 rounded-lg text-sm shadow-sm transition-all active:scale-[0.98]"
                        >
                            Acceder
                        </button>
                    </div>
                )}
            </form>

            <p className="mt-8 text-center text-[10px] text-neutral-300 uppercase font-bold tracking-widest">
                Demo access: 1234
            </p>
        </div>
    </div>
  );
};

